def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    live_prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 6:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0)
            prev_bids.append(bid)
            live_prev_bids.append(bid)

    highest_prev = max(live_prev_bids) if live_prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_medium = supply <= 20
    urgent = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2

    if critical:
        base = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif urgent:
        base = max(DAILY_SALARY * 0.82, highest_prev + 1.5)
    else:
        if supply_tight:
            base = max(DAILY_SALARY * 0.78, highest_prev + 1.0)
        elif supply_medium:
            base = max(DAILY_SALARY * 0.62, avg_prev * 0.72)
        else:
            base = max(DAILY_SALARY * 0.42, avg_prev * 0.52)

    if desperate_count >= 2:
        base += 4.0
    elif desperate_count == 1:
        base += 2.0

    if rich_count >= 2 and supply_tight:
        base += 3.0

    if day >= 8 and hp > 4 and no_water == 0 and not supply_tight:
        base *= 0.9

    if budget < DAILY_SALARY * 1.2:
        base = min(base, budget)
    elif budget > DAILY_SALARY * 8 and urgent:
        base += 3.0

    bid = min(budget, max(0.0, base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 90
    WATER_REQ = 9

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_supply = day_context['supply']

    strong_opponents_ids = ["Alex", "Cindy"]

    highest_prev_bid_strong_opponents = 0.0

    for opp_id in strong_opponents_ids:
        if opp_id in opponents_status and opponents_status[opp_id]['alive']:
            prev_trace = opponents_status[opp_id].get('previous_trace')
            if prev_trace and prev_trace.get('bid') is not None:
                highest_prev_bid_strong_opponents = max(highest_prev_bid_strong_opponents, prev_trace['bid'])

    num_active_players = 1 # Me
    for opp_data in opponents_status.values():
        if opp_data['alive']:
            num_active_players += 1

    num_full_req_possible = int(current_supply / WATER_REQ)

    base_bid = DAILY_SALARY

    if my_current_hp <= 2:
        my_bid = base_bid * 1.25 # Critical HP, bid very aggressively
    elif my_current_hp <= 4:
        my_bid = base_bid * 1.15 # Low HP, bid aggressively
    elif my_current_hp >= 8:
        my_bid = base_bid * 0.9 # Healthy HP, can be more conservative
    else:
        my_bid = base_bid # Moderate HP

    if highest_prev_bid_strong_opponents > 0:
        if num_active_players > num_full_req_possible:
            # High competition scenario
            if my_current_hp <= 4:
                # Critical/low HP, must win, bid higher than opponent's max previous bid
                my_bid = max(my_bid, highest_prev_bid_strong_opponents * 1.05)
            else:
                # Healthy, try to win but don't overspend too much
                my_bid = max(my_bid, highest_prev_bid_strong_opponents * 1.01)
        else:
            # Lower competition, can try to win with slightly less than opponent's max previous bid
            my_bid = max(my_bid, highest_prev_bid_strong_opponents * 0.98)
    else:
        # No strong opponent bids from yesterday, or they didn't bid high.
        # Adjust based on general competition for supply
        if num_active_players > num_full_req_possible:
            my_bid *= 1.05 # Increase bid if competition is high for available slots
        else:
            my_bid *= 0.95 # Decrease bid if competition is low

    my_bid = min(my_bid, my_current_budget)
    my_bid = max(0.0, my_bid)

    return my_bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], max(avg_prev * 1.2, DAILY_SALARY * 0.9))
    else:
        bid = min(my_status['budget'], avg_prev * 0.95)

    return float(max(0, bid))
